const INSTANCE_COUNT = 3000;

const vs3D_Default =
`#version 300 es
layout (location = 0) in vec3 aPosition;
layout (location = 1) in vec3 aNormal;
layout (location = 2) in vec3 aOffsetPosition;
layout (location = 3) in mat3 aOffsetRotation;

out vec3 vLocalPosition;  // positionの生データ
out vec3 vGlobalPosition; // モデル変換したposition
out vec3 vViewPosition;   // view座標におけるposition
out vec3 vLocalNormal;    // normalの生データ
out vec3 vGlobalNormal;   // モデル変換したnormal
out vec3 vViewNormal;     // view座標におけるnormal

uniform mat4 uModelMatrix;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjMatrix;
uniform mat3 uNormalMatrix;
uniform mat3 uModelNormalMatrix;

void main(){
  // preProcess
  vec3 position = aPosition;
  vec3 normal = aNormal;

  position = ((0.05 * position) * aOffsetRotation) + 2.0*aOffsetPosition;

  // ベクトルに行列を掛けるのは右から。
