    // これで全部のはず。
    gl.useProgram(pgNormal);
    setUniformValue(gl, pgNormal, "matrix4fv", "uProjMatrix", projMatrix.m);

    // torus
    gl.bindVertexArray(vaoTorus);

    // model変換
    modelMatrix.init();
    modelViewMatrix.set(viewMatrix.multM(modelMatrix, true));

