function createVAO(gl, pg, v, n, f){
  const vao = gl.createVertexArray();
  const pLocation = pg.attributes.aPosition.location;
  const nLocation = pg.attributes.aNormal.location;
  const vertexCount = Math.floor(v.length/3);

  gl.bindVertexArray(vao);

  const pBuf = gl.createBuffer();
  const positionArray = new Float32Array(v);
  gl.bindBuffer(gl.ARRAY_BUFFER, pBuf);
  gl.bufferData(gl.ARRAY_BUFFER, positionArray, gl.STATIC_DRAW);
  gl.vertexAttribPointer(pLocation, 3, gl.FLOAT, false, 0, 0);
  gl.enableVertexAttribArray(pLocation);

  const nBuf = gl.createBuffer();
  const normalArray = new Float32Array(n);
  gl.bindBuffer(gl.ARRAY_BUFFER, nBuf);
  gl.bufferData(gl.ARRAY_BUFFER, normalArray, gl.STATIC_DRAW);
  gl.vertexAttribPointer(nLocation, 3, gl.FLOAT, false, 0, 0);
  gl.enableVertexAttribArray(nLocation);

  gl.bindBuffer(gl.ARRAY_BUFFER, null); // これはカプセル化の対象外なのでヌルバする

  const iBuf = gl.createBuffer();
  const indexArray = (vertexCount <= 65536 ? new Uint16Array(f) : new Uint32Array(f));
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, iBuf);
  gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, indexArray, gl.STATIC_DRAW);

  gl.bindVertexArray(null);
  vao.faceLength = f.length;
  vao.indexBufferType = (vertexCount <= 65536 ? gl.UNSIGNED_SHORT : gl.UNSIGNED_INT);

  return vao;
}

