class Quarternion{
  constructor(w = 1, x = 0, y = 0, z = 0){
    this.w = w;
    this.x = x;
    this.y = y;
    this.z = z;
  }
  set(q){
    if(arguments.length === 4){
      this.w = arguments[0];
      this.x = arguments[1];
      this.y = arguments[2];
      this.z = arguments[3];
      return this;
    }
    this.w = q.w;
    this.x = q.x;
    this.y = q.y;
    this.z = q.z;
    return this;
  }
  multQ(q, immutable = false){
    if(immutable){
      const r = new Quarternion();
      r.w = this.w * q.w - this.x * q.x - this.y * q.y - this.z * q.z;
      r.x = this.w * q.x + this.x * q.w + this.y * q.z - this.z * q.y;
      r.y = this.w * q.y + this.y * q.w + this.z * q.x - this.x * q.z;
      r.z = this.w * q.z + this.z * q.w + this.x * q.y - this.y * q.x;
      return r;
    }
    const {w:d, x:a, y:b, z:c} = this;
    this.w = d * q.w - a * q.x - b * q.y - c * q.z;
    this.x = d * q.x + a * q.w + b * q.z - c * q.y;
    this.y = d * q.y + b * q.w + c * q.x - a * q.z;
    this.z = d * q.z + c * q.w + a * q.y - b * q.x;
    return this;
  }
  applyV(v){
    // vに適用する。軸と角度。
    // 具体的にはq * v * \bar{q} を計算してx,y,zを取るだけ。
    const q = this.copy();
    const vq = Quarternion.fromV(v);
    const qConj = q.conj(true); // ここのqは変えちゃまずいのでtrueです。
    // qは変えちゃってOK
    q.multQ(vq).multQ(qConj);
    // これが回転になってるかどうかは知らないです。検証すべき点が
    // 多すぎて追いつかないです。
    return new Vecta(q.x, q.y, q.z);
  }
  conj(immutable = false){
    if(immutable){
      var q = new Quarternion();
      q.w = this.w;
      q.x = -this.x;
      q.y = -this.y;
      q.z = -this.z;
      return q;
    }
    this.x *= -1;
    this.y *= -1;
    this.z *= -1;
    return this;
  }
  copy(){
    return new Quarternion(this.w, this.x, this.y, this.z);
  }
  static fromAA(axis, angle){
    // 軸の指定方法は3種類
    if(Array.isArray(axis)){
      axis = new Vecta(axis[0], axis[1], axis[2]);
    }else if(arguments.length === 4){
      axis = new Vecta(arguments[0], arguments[1], arguments[2]);
      angle = arguments[3];
    }
    axis.normalize();
    var q = new Quarternion();
    q.w = Math.cos(angle/2);
    var s = Math.sin(angle/2);
    q.x = axis.x * s;
    q.y = axis.y * s;
    q.z = axis.z * s;
    return q;
  }
  static fromV(v){
    var q = new Quarternion();
    q.w = 0;
    q.x = v.x;
    q.y = v.y;
    q.z = v.z;
    return q;
  }
}

// 更新の際はまずクォータニオンにアクセスしたうえで...
// むずかしいわね
// アースローテーション：
// centerとnorth固定、northの周りの横回転と、frontがnorthに近づく縦回転
// frontとnorthのなす角を調べて0+0.000001～Math.PI-0.000001に収まるようにする
// フリーローテーション：
// centerのみ固定、northは一緒に動く。
// いずれもクォータニオンを更新したのち
// axesをクォータニオンから更新して
// 更新されたaxesをもとにviewも更新
// eyeは距離を保存しておいてcenterとfrontから出す
// northはクォータニオンサンドイッチで計算すればいいかと
class QCamera{
  constructor(params = {}){
    const {eye = [0,1,3], center = [0,0,0], north = [0,1,0]} = params;
    this.eye = (eye instanceof Vecta ? eye : Vecta.create(eye));
    this.center = (center instanceof Vecta ? center : Vecta.create(center));
    this.north = (north instanceof Vecta ? north : Vecta.create(north));
    this.front = new Vecta();
    this.side = new Vecta();
    this.up = new Vecta();
    this.calcAxesFromParam();
    this.q = new Quarternion();
    this.calcQuarternion();
    this.view = new MT4();
    this.calcView();
  }
  setParam(params = {}){
    // eye, center, northのうちいくつかを更新
    const {eye, center, north} = params;
    if(eye !== undefined){
      this.eye = (eye instanceof Vecta ? eye : Vecta.create(eye));
    }
    if(center !== undefined){
      this.center = (center instanceof Vecta ? center : Vecta.create(center));
    }
    if(north !== undefined){
      this.north = (north instanceof Vecta ? north : Vecta.create(north));
    }
    this.calcAxesFromParam();
    this.calcQuarternion();
    this.calcView();
    return this;
  }
  calcAxesFromParam(){
    // frontはeyeからcenterを引く
    this.front.set(this.eye).sub(this.center).normalize();
    const _side = this.north.cross(this.front, true);
    this.side.set(_side).normalize();
    const _up = this.front.cross(this.side, true);
    this.up.set(_up).normalize();
    // それぞれz,x,yに当たる
  }
  calcAxesFromQuarternion(){
    const {w,x,y,z} = this.q;
    // 縦横バグってました。ごめんなさい。
    // 成分を横に並べるからバグりやすいのよね。
    // でもイメージとしてはやっぱ列ベクトルの方が分かりやすいのよ。
    // それでも。
    this.side.set(2*w*w-1 + 2*x*x, 2*(x*y + z*w), 2*(x*z - y*w));
    this.up.set(2*(x*y - z*w), 2*w*w-1 + 2*y*y, 2*(y*z + x*w));
    this.front.set(2*(x*z + y*w), 2*(y*z - x*w), 2*w*w-1 + 2*z*z);
  }
  calcQuarternion(){
    // 直交行列からクォータニオンを出す例の方法
    // https://github.com/mrdoob/three.js/blob/r172/src/math/Quaternion.js#L294
    const {x:a, y:d, z:g} = this.side;
    const {x:b, y:e, z:h} = this.up;
    const {x:c, y:f, z:i} = this.front;
    // a  b  c
    // d  e  f
    // g  h  i
    const trace = a + e + i;
    // 角度がPIに近いと割り算ができないが、
    // traceが正ならそれは起きえない。
    if(trace > 0){
      this.q.w = Math.sqrt((trace + 1) / 4);
      var factor = 0.25/this.q.w; // あー、this.wじゃないですね。
      this.q.x = (h - f)*factor;
      this.q.y = (c - g)*factor;
      this.q.z = (d - b)*factor;
    }else{
      if(a > e && a > i){
        // aが最大の場合
        var s = 2 * Math.sqrt(1 + a - e - i);
        this.q.w = (h - f) / s;
        this.q.x = 0.25 * s;
        this.q.y = (b + d) / s;
        this.q.z = (c + g) / s;
      }else if(e > i){
        // eが最大の場合
        var s = 2 * Math.sqrt(1 + e - i - a);
        this.q.w = (c - g) / s;
        this.q.x = (b + d) / s;
        this.q.y = 0.25 * s;
        this.q.z = (f + h) / s;
      }else{
        // iが最大の場合
        var s = 2 * Math.sqrt(1 + i - a - e);
        this.q.w = (d - b) / s;
        this.q.x = (c + g) / s;
        this.q.y = (f + h) / s;
        this.q.z = 0.25 * s;
      }
    }
  }
  calcView(){
    // front, side, upから行列を作るだけ。
    this.view.set([
      this.side.x, this.side.y, this.side.z, 0,
      this.up.x, this.up.y, this.up.z, 0,
      this.front.x, this.front.y, this.front.z, 0,
      0, 0, 0, 1
    ]);
    this.view.multM([
      1, 0, 0, -this.eye.x,
      0, 1, 0, -this.eye.y,
      0, 0, 1, -this.eye.z,
      0, 0, 0, 1
    ]);
  }
  getViewMatrix(){
    return this.view;
  }
  spin(delta){
    // northの周りにangleだけ、正方向に回転させる。上から見て正。右ねじ。
    // qをいじり、axesを更新し、eyeを更新し、viewを更新する。
    const qSpin = Quarternion.fromAA(this.north, delta);
    // グローバルなので左乗算
    qSpin.multQ(this.q);
    this.q.set(qSpin);
    // ここがバグってたんですが解消しました。めんどくさ...
    this.calcAxesFromQuarternion();
    const d = this.eye.dist(this.center);
    this.eye.set(this.center).addScalar(this.front, d);
    this.calcView();
    return this;
  }
  angle(delta){
    // sideの周りのローカル回転。正方向に回転させる。なのでy→zですか。northと
    // frontのなす角をthetaとして0とPIにおさまるようにする
    var theta = Math.abs(this.north.angleBetween(this.front));
    // で、
    const updatedAngle = Math.min(Math.max(theta + delta, 0.000001), Math.PI-0.000001);
    const properDelta = updatedAngle - theta;
    const qAngle = Quarternion.fromAA(1,0,0,properDelta);
    // ローカルなので右乗算
    this.q.multQ(qAngle);
    this.calcAxesFromQuarternion();
    var d = this.eye.dist(this.center);
    this.eye.set(this.center).addScalar(this.front, d);
    this.calcView();
    return this;
  }
  lookAt(v){
    // vはベクトルとする。centerをvに移すだけ。
    if(arguments.length === 3){
      v = new Vecta(arguments[0], arguments[1], arguments[2]);
    }
    const difference = v.sub(this.center);
    this.center.add(difference);
    this.eye.add(difference);
    this.calcView();
    return this;
  }
}

